INSERT INTO `news` (`id_news`, `title`, `summary`, `content`, `publish_date`, `expiration_date`, `id_user`, `university`, `theme`, `image`, `status`, `date_added`, `date_updated`, `date_deleted`) VALUES
(20, ' Visite du Professeur Lukas Pairon à l’UCC : Echanges autour de la recherche doctorale', NULL, '<p><span style=\"font-size: 14pt;\">Dans le cadre de la coop&eacute;ration interuniversitaire, <strong>la Facult&eacute; d&rsquo;&Eacute;conomie et D&eacute;veloppement de l\'UCC</strong> a accueilli, ce jeudi 29 mai 2025, le Professeur <strong>Dr Lukas Pairon de l&rsquo;Universit&eacute; de Gand (Belgique)</strong>.</span></p>\r\n<p><span style=\"font-size: 12pt;\">Lors d&rsquo;un &eacute;change enrichissant avec les assistants de la facult&eacute;, le Professeur Pairon a partag&eacute; des pistes concr&egrave;tes sur les perspectives de recherche doctorale.</span></p>\r\n<p><span style=\"font-size: 12pt;\">Il a insist&eacute; sur l&rsquo;importance de :</span></p>\r\n<ul>\r\n<li style=\"font-style: italic;\"><em><span style=\"font-size: 12pt;\">D&eacute;gager du temps pour la recherche ;</span></em></li>\r\n<li style=\"font-style: italic;\"><em><span style=\"font-size: 12pt;\">Multiplier les &eacute;changes r&eacute;guliers avec des personnes ressources du domaine ; et</span></em></li>\r\n<li style=\"font-style: italic;\"><em><span style=\"font-size: 12pt;\">Capitaliser sur leur exp&eacute;rience professionnelle afin de mener des recherches ancr&eacute;es dans les r&eacute;alit&eacute;s sociales.</span></em></li>\r\n</ul>\r\n<p><span style=\"font-size: 12pt;\">Satisfaits de cette rencontre inspirante, les assistants ont exprim&eacute; leur profonde gratitude &agrave; Madame la Doyenne pour cette initiative particuli&egrave;rement b&eacute;n&eacute;fique.</span></p>', '2025-05-29 07:14:48', NULL, NULL, 13, 'Tout', '1751459003_d7edd8ce1cb11aa3252c.jpg', 'brouillon', '2025-06-04 05:14:48', '2025-07-02 11:09:31', '2025-07-02 11:09:31'),
(21, 'Représentation brillante de l\'UCC à Lille en France', NULL, '<p><strong><span style=\"font-size: 14pt;\">Pascaline KABEMBA, doctorante en 2e ann&eacute;e en Communications sociales &agrave; l&rsquo;UCC, a particip&eacute; ce 22 mai 2025 &agrave; la 19e Journ&eacute;e des jeunes chercheur&middot;e&middot;s en SIC organis&eacute;e par le laboratoire G&eacute;riico de l&rsquo;Universit&eacute; de Lille</span></strong> .</p>\r\n<p>Son intervention portait&nbsp;sur : &laquo; <em>Aux sources africaines des mod&egrave;les de communication : la palabre africaine</em> &raquo;.</p>\r\n<p>Elle a interrog&eacute; la mani&egrave;re dont les Sciences de l&rsquo;Information et de la Communication abordent les crises qui frappent l&rsquo;Afrique depuis les ann&eacute;es 60, en critiquant les limites des paradigmes occidentaux souvent inadapt&eacute;s aux r&eacute;alit&eacute;s africaines.</p>\r\n<p>Pascaline a propos&eacute; la palabre africaine comme mod&egrave;le de communication endog&egrave;ne efficace, ancr&eacute; dans le dialogue, le consensus et les valeurs communautaires.</p>\r\n<p>Elle appelle &agrave; une reconnaissance des pratiques communicationnelles africaines et &agrave; une relecture critique des paradigmes pour mieux comprendre et pr&eacute;venir les crises sur le continent.</p>\r\n<p><em><strong>F&eacute;licitations &agrave; elle pour ce plaidoyer courageux en faveur des savoirs africains ! </strong></em></p>', '2025-05-22 07:18:35', NULL, NULL, 11, 'Tout', '1749021515_61516599c572a04c9dec.jpg', 'brouillon', '2025-06-04 05:18:35', '2025-07-02 11:17:03', NULL);
INSERT INTO `news` (`id_news`, `title`, `summary`, `content`, `publish_date`, `expiration_date`, `id_user`, `university`, `theme`, `image`, `status`, `date_added`, `date_updated`, `date_deleted`) VALUES
(23, 'Journée scientifique à l’Université Don Bosco de Lubumbashi : Réflexion collective pour une paix durable en RDC', NULL, '<p><span style=\"font-size: 14pt;\">Ce&nbsp;samedi 31 mai 2025, la Facult&eacute; des sciences de l&rsquo;homme et de la soci&eacute;t&eacute; de l&rsquo;Universit&eacute; Don Bosco de Lubumbashi a accueilli la 2ᵉ &eacute;dition des Journ&eacute;es scientifiques sur le th&egrave;me : &laquo;<strong> Justice, Paix et Droits : Promouvoir la culture de la paix en RDC </strong>&raquo;.</span></p>\r\n<p>Un sujet profond&eacute;ment actuel, choisi pour &eacute;voquer les enjeux d&rsquo;une soci&eacute;t&eacute; congolaise en qu&ecirc;te de paix, de justice et de stabilit&eacute;, mais aussi pour r&eacute;v&eacute;ler l&rsquo;espoir d&rsquo;un peuple tourn&eacute; vers une identit&eacute; commune et un avenir harmonieux.</p>\r\n<p>Une journ&eacute;e marqu&eacute;e par des interventions de haut niveau : Des professeurs d&rsquo;universit&eacute;, religieux, chercheurs et &eacute;tudiants se sont r&eacute;unis autour de r&eacute;flexions cl&eacute;s :</p>\r\n<ul>\r\n<li style=\"font-style: italic;\"><em>&laquo;L&rsquo;aspiration &agrave; la paix : fondement anthropologique &raquo; par le P&egrave;re David Mubenga;</em></li>\r\n<li style=\"font-style: italic;\"><em>&laquo;&nbsp;L&rsquo;&eacute;conomie au service de la paix : promouvoir une prosp&eacute;rit&eacute; partag&eacute;e &raquo; par le Prof. F&eacute;lix Kalaba;</em></li>\r\n<li style=\"font-style: italic;\"><em>&laquo;&nbsp;Droits de l&rsquo;homme et justice : leviers de paix en RDC &raquo; par Me. Marla Katapala.</em></li>\r\n</ul>\r\n<p>Des &eacute;changes nourris ont pr&eacute;c&eacute;d&eacute; un second panel :&nbsp;&nbsp;&laquo; L&rsquo;&eacute;cologie int&eacute;grale au service de la paix durable &raquo; par le P&egrave;re Dieudonn&eacute; Besa;</p>\r\n<ul>\r\n<li style=\"font-style: italic;\"><em>&laquo; La p&eacute;dagogie sal&eacute;sienne : Bons chr&eacute;tiens et honn&ecirc;tes citoyens &raquo; par le P&egrave;re Dieudonn&eacute; Makola;</em></li>\r\n<li style=\"font-style: italic;\"><em>&laquo;&nbsp;L&rsquo;&eacute;ducation &agrave; la paix pour une cohabitation pacifique &raquo; par le P&egrave;re Pierre Maibwe.</em></li>\r\n</ul>\r\n<p>Enfin, deux conf&eacute;rences de cl&ocirc;ture d\'une grande richesse :&nbsp;&nbsp;</p>\r\n<ul>\r\n<li style=\"font-style: italic;\"><em>&laquo; Le&nbsp;r&ocirc;le de l&rsquo;&Eacute;glise dans l&rsquo;&eacute;dification de la paix &raquo; par l\'Abb&eacute; Bertin Mpemba&nbsp;</em></li>\r\n<li><em>&laquo;&nbsp;Quelle diplomatie pour la paix en RDC ? &raquo; du Prof. F&eacute;licien Mulamba.</em></li>\r\n</ul>\r\n<p><em><img src=\"data:image/jpeg;base64,\" width=\"400\" height=\"267\"></em></p>\r\n<p>Le mot de cl&ocirc;ture du P&egrave;re Trufon Kilimira, vicaire provincial des Sal&eacute;siens de Don Bosco, a soulign&eacute; la pertinence des &eacute;changes et la profondeur des analyses propos&eacute;es.</p>', '2025-05-31 07:33:38', NULL, NULL, 6, 'Tout', '1751455972_a4be5844cad2c0c175ad.jpg', 'brouillon', '2025-06-04 05:33:38', '2025-07-02 11:10:09', '2025-07-02 11:10:09'),
(24, 'la première ministre judith suminwa en visite à l’université notre-dame du kasayi', NULL, '<div data-wow-delay=\"0.3s\">\r\n<p><span style=\"font-size: 18.6667px;\">Test Update</span></p>\r\n<p>Accueillie par la Rectrice, Professeure Ordinaire Jos&eacute;phine Bitota Muamba, la cheffe du gouvernement a salu&eacute; l&rsquo;engagement remarquable de l&rsquo;UKA dans la formation de l&rsquo;&eacute;lite congolaise.</p>\r\n<p>&laquo;&nbsp;<em>Je suis impressionn&eacute;e par les r&eacute;alisations de cette universit&eacute;. Je f&eacute;licite les autorit&eacute;s pour les efforts consentis sur fonds propres. Vous avez ma parole d\'honneur : le gouvernement soutiendra vos initiatives </em>&raquo;, a-t-elle d&eacute;clar&eacute; devant la communaut&eacute; universitaire.</p>\r\n<p>Elle a &eacute;galement appel&eacute; les &eacute;tudiants &agrave; incarner les valeurs civiques et morales essentielles au d&eacute;veloppement du pays, tout en mettant en avant l&rsquo;importance de l&rsquo;entrepreneuriat des jeunes, conform&eacute;ment &agrave; la vision du Pr&eacute;sident F&eacute;lix Tshisekedi.</p>\r\n<p>Accompagn&eacute;e du <em>Gouverneur Mo&iuml;se Kambulu</em>, Madame Suminwa a&nbsp;visit&eacute; les laboratoires de la facult&eacute; de m&eacute;decine ainsi que le site destin&eacute; &agrave; abriter les futures Cliniques universitaires.</p>\r\n<p><strong><em>La&nbsp;Rectrice de l&rsquo;UKA s&rsquo;est r&eacute;jouie de cette visite, qu&rsquo;elle a qualifi&eacute;e de soutien fort &agrave; l&rsquo;enseignement sup&eacute;rieur et &agrave; la jeunesse intellectuelle congolaise.</em></strong></p>\r\n</div>', '2025-05-24 07:42:19', NULL, NULL, 2, 'Tout', '1751460176_beb4fe48338504e01cc9.jpg', 'brouillon', '2025-06-04 05:42:19', '2025-07-02 11:07:22', '2025-07-02 11:07:22');
INSERT INTO `news` (`id_news`, `title`, `summary`, `content`, `publish_date`, `expiration_date`, `id_user`, `university`, `theme`, `image`, `status`, `date_added`, `date_updated`, `date_deleted`) VALUES
(28, 'L’Université Catholique du Congo (UCC) célèbre la rentrée académique 2025-2026 sous le signe de la foi et de l’excellence', NULL, '<p data-start=\"244\" data-end=\"754\"><strong data-start=\"244\" data-end=\"278\">Kinshasa, le 30 septembre 2025</strong> &mdash; C&rsquo;est dans une atmosph&egrave;re solennelle et porteuse d&rsquo;espoir que la communaut&eacute; universitaire de l&rsquo;Universit&eacute; Catholique Saint-Augustin (UCSA) a lanc&eacute; officiellement l&rsquo;ann&eacute;e acad&eacute;mique 2025-2026. La c&eacute;r&eacute;monie d&rsquo;ouverture, pr&eacute;sid&eacute;e par Monseigneur Andr&eacute; Tshiswaka, &eacute;v&ecirc;que du dioc&egrave;se de Kinshasa, s&rsquo;est d&eacute;roul&eacute;e en pr&eacute;sence du corps professoral, des &eacute;tudiants, du personnel administratif ainsi que de plusieurs invit&eacute;s de marque issus du monde acad&eacute;mique, politique et eccl&eacute;sial.</p>\r\n<h4 data-start=\"756\" data-end=\"821\">✝️ Une rentr&eacute;e plac&eacute;e sous le th&egrave;me de l\'engagement chr&eacute;tien</h4>\r\n<p data-start=\"823\" data-end=\"1234\">Le th&egrave;me retenu cette ann&eacute;e &mdash; <em data-start=\"853\" data-end=\"908\">&laquo; Foi vivante, savoir &eacute;clair&eacute;, service d&eacute;sint&eacute;ress&eacute; &raquo;</em> &mdash; traduit la volont&eacute; de l&rsquo;universit&eacute; de former des leaders comp&eacute;tents et ancr&eacute;s dans les valeurs de l&rsquo;&Eacute;vangile. Dans son hom&eacute;lie, Monseigneur Tshiswaka a rappel&eacute; que la mission premi&egrave;re d&rsquo;une universit&eacute; catholique est de &laquo; faire rayonner la v&eacute;rit&eacute; dans toutes les disciplines du savoir, en y int&eacute;grant la lumi&egrave;re de la foi &raquo;.</p>\r\n<p data-start=\"1236\" data-end=\"1413\">La messe d&rsquo;ouverture a &eacute;t&eacute; suivie par un discours inspirant du Recteur, le Professeur Henri Mbuyi, qui a soulign&eacute; les d&eacute;fis et les priorit&eacute;s de cette nouvelle ann&eacute;e, notamment :</p>\r\n<ul data-start=\"1414\" data-end=\"1679\">\r\n<li data-start=\"1414\" data-end=\"1464\">\r\n<p data-start=\"1416\" data-end=\"1464\">Le renforcement de la qualit&eacute; de l&rsquo;enseignement,</p>\r\n</li>\r\n<li data-start=\"1465\" data-end=\"1508\">\r\n<p data-start=\"1467\" data-end=\"1508\">L&rsquo;insertion professionnelle des dipl&ocirc;m&eacute;s,</p>\r\n</li>\r\n<li data-start=\"1509\" data-end=\"1584\">\r\n<p data-start=\"1511\" data-end=\"1584\">La promotion de la recherche appliqu&eacute;e au service du d&eacute;veloppement local,</p>\r\n</li>\r\n<li data-start=\"1585\" data-end=\"1679\">\r\n<p data-start=\"1587\" data-end=\"1679\">Et l&rsquo;int&eacute;gration plus pouss&eacute;e des questions d&rsquo;&eacute;thique et de citoyennet&eacute; dans les programmes.</p>\r\n</li>\r\n</ul>\r\n<h4 data-start=\"1681\" data-end=\"1738\">🎒 Un accueil chaleureux pour les nouveaux &eacute;tudiants</h4>\r\n<p data-start=\"1740\" data-end=\"2036\">Plus de 1 200 nouveaux &eacute;tudiants ont &eacute;t&eacute; officiellement accueillis au sein de l&rsquo;UCSA. &Agrave; travers des activit&eacute;s d&rsquo;orientation organis&eacute;es par le Bureau de la Vie &Eacute;tudiante, ces jeunes d&eacute;couvrent un environnement propice &agrave; l&rsquo;excellence acad&eacute;mique, &agrave; la croissance personnelle et &agrave; la vie spirituelle.</p>\r\n<p data-start=\"2038\" data-end=\"2349\">Des &eacute;tudiants plus anciens ont &eacute;galement partag&eacute; leurs exp&eacute;riences et prodigu&eacute; de pr&eacute;cieux conseils : &laquo; Ici, on apprend non seulement pour soi, mais aussi pour les autres. L&rsquo;universit&eacute; nous pousse &agrave; r&eacute;fl&eacute;chir, &agrave; prier, et &agrave; agir pour changer le monde &raquo;, confie Clarisse, &eacute;tudiante en troisi&egrave;me ann&eacute;e d&rsquo;&eacute;conomie.</p>\r\n<h4 data-start=\"2351\" data-end=\"2404\">📣 Un appel &agrave; la responsabilit&eacute; et &agrave; l&rsquo;esp&eacute;rance</h4>\r\n<p data-start=\"2406\" data-end=\"2619\">La c&eacute;r&eacute;monie s&rsquo;est cl&ocirc;tur&eacute;e par un moment de pri&egrave;re interconfessionnelle, suivi d&rsquo;un cocktail fraternel. L&rsquo;ambiance &eacute;tait &agrave; la fois festive et studieuse, marqu&eacute;e par l&rsquo;enthousiasme de toutes les parties prenantes.</p>\r\n<p data-start=\"2621\" data-end=\"2855\">Le message est clair : &agrave; l&rsquo;UCSA, la rentr&eacute;e acad&eacute;mique n&rsquo;est pas un simple &eacute;v&eacute;nement administratif. C&rsquo;est un v&eacute;ritable moment de communion, de relance de la mission &eacute;ducative et de t&eacute;moignage de l&rsquo;&Eacute;glise au c&oelig;ur du monde intellectuel.</p>\r\n<hr data-start=\"2857\" data-end=\"2860\">\r\n<p data-start=\"2862\" data-end=\"3042\"><strong data-start=\"2862\" data-end=\"2912\">📝 R&eacute;daction : Service Communication de l&rsquo;UCSA</strong><br data-start=\"2912\" data-end=\"2915\"><strong data-start=\"2915\" data-end=\"2959\">📸 Cr&eacute;dit photos : J. Kanda &ndash; UCSA Media</strong><br data-start=\"2959\" data-end=\"2962\"><strong data-start=\"2962\" data-end=\"3042\">📩 Vous avez une actualit&eacute; &agrave; partager ? &Eacute;crivez-nous &agrave; <a class=\"cursor-pointer\" rel=\"noopener\" data-start=\"3019\" data-end=\"3040\">communication@ucsa.cd</a></strong></p>', '2025-07-02 10:12:16', NULL, NULL, 11, 'Tout', '1751451136_fbb1ed4b1edc12300b8b.jpg', 'brouillon', '2025-07-02 08:12:16', '2025-07-02 11:06:47', '2025-07-02 11:06:47'),
(29, 'Tendances majeures dans l’enseignement supérieur catholique : fermetures, restructurations et expansion', NULL, '<h4 data-start=\"824\" data-end=\"879\">Fermeture programm&eacute;e de Siena Heights University</h4>\r\n<p data-start=\"880\" data-end=\"1000\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Fond&eacute;e en 1919 &agrave; Adrian, Michigan, Siena Heights a annonc&eacute; qu\'elle fermerait fin 2026 en raison de pressions financi&egrave;res croissantes. Malgr&eacute; tout, l\'&eacute;cole promet une derni&egrave;re ann&eacute;e acad&eacute;mique enrichie et un soutien soutenu aux &eacute;tudiants pour leur transfert</span> <span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Cette fermeture marque la fin d&rsquo;une institution centenaire, symbole des d&eacute;fis auxquels font face les petites universit&eacute;s priv&eacute;es am&eacute;ricaines.</span></p>\r\n<h4 data-start=\"1002\" data-end=\"1071\">R&eacute;organisation strat&eacute;gique &agrave; la Catholic University of America</h4>\r\n<p data-start=\"1072\" data-end=\"1194\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Face &agrave; un d&eacute;ficit structurel de 30 millions de dollars, l&rsquo;universit&eacute; bas&eacute;e &agrave; Washington D.C. envisage des fusions internes : la School of Music, Drama, and Art pourrait dispara&icirc;tre, ses disciplines r&eacute;parties dans d\'autres facult&eacute;s, tandis que la School of Social Service fusionnerait avec celle des sciences infirmi&egrave;res</span>&nbsp;<br data-start=\"1152\" data-end=\"1155\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Une d&eacute;marche difficile mais jug&eacute;e n&eacute;cessaire pour pr&eacute;server la qualit&eacute; des formations et l&rsquo;avenir de l\'&eacute;tablissement.</span></p>\r\n<h4 data-start=\"1196\" data-end=\"1245\">Un projet d&rsquo;universit&eacute; catholique au Gabon</h4>\r\n<p data-start=\"1246\" data-end=\"1458\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">&Agrave; Libreville, le Saint‑Si&egrave;ge ambitionne de cr&eacute;er une nouvelle universit&eacute; catholique. Le projet, soutenu par les autorit&eacute;s gabonaises et int&eacute;gr&eacute; dans la strat&eacute;gie &laquo; Gabon num&eacute;rique &raquo;, vise &agrave; enrichir l&rsquo;offre d&rsquo;enseignement sup&eacute;rieur locale</span>&nbsp;<br data-start=\"1326\" data-end=\"1329\">Un signe fort de l&rsquo;&Eacute;glise qui, au-del&agrave; de l&rsquo;Europe et de l&rsquo;Am&eacute;rique, s&rsquo;affirme comme acteur de d&eacute;veloppement &eacute;ducatif en Afrique.</p>', '2025-07-02 15:49:02', NULL, NULL, 10, 'Tout', '1751471557_7fb4096b05595a26ad40.jpg', 'brouillon', '2025-07-02 13:49:02', '2025-07-02 13:52:37', NULL);

