(2, 1, 'Université Maria Malkia (UMM)', 'Lubumbashi', '', '126 Avenue Mgr J.F de Hemptine (ex Tabora), Commune de Lubumbashi, RDC - Lubumbashi', 'info@univsersitemariamalkia.com', '+243896563608', 'https://universitemariamalkia.com/', '1751469889_25b29571e03d9de42236.jpeg', NULL, '2025-05-29 14:05:29', '2025-07-02 13:51:49', '2025-07-02 13:51:49'),
(3, 1, 'Institut Supérieur Interdiocésain Monseigneur Mulolwa (ISIM)', 'Lubumbahi', '', '', '', '', '', NULL, NULL, '2025-05-29 14:05:29', '2025-07-02 13:51:57', '2025-07-02 13:51:57'),
(4, 1, 'Université Don Bosco de Lubumbashi (UDBL)', '', '<p><a href=\"https://ius-sdb.com/democratic-republic-congo-quality-higher-education-don-bosco-university-in-lubumbashi/\"><img src=\"https://images.openai.com/thumbnails/url/7a5n7Xicu1mSUVJSUGylr5-al1xUWVCSmqJbkpRnoJdeXJJYkpmsl5yfq5-Zm5ieWmxfaAuUsXL0S7F0Tw50qQqLLCrKjkjx80gs1C03djaPDDTMSSnLc3Euz8jLKQ129DUIDPYxTDL0S3cP8S6zcAxMKk73rrIMd1QrBgAk8inJ\" alt=\"ius-sdb.com/democratic-r...\"></a></p>\r\n<p>Voici un panorama complet et &agrave; jour sur l&rsquo;<strong>Universit&eacute; Don Bosco de Lubumbashi (UDBL)</strong> :</p>\r\n<hr>\r\n<h2>Situation et origine</h2>\r\n<ul>\r\n<li>\r\n<p><strong>Cr&eacute;&eacute;e en 2023</strong> &agrave; Lubumbashi, Haut‑Katanga, RDC &rarr; r&eacute;sultat de la fusion de quatre &eacute;tablissements sal&eacute;siens : ESIS (informatique), ECOPO (gestion), Institut Saint‑Jean Bosco (philosophie) et Institut Saint‑Fran&ccedil;ois de Sales (th&eacute;ologie)</p>\r\n</li>\r\n<li>\r\n<p>Premi&egrave;re <strong>universit&eacute; sal&eacute;sienne</strong> en <strong>Afrique</strong></p>\r\n</li>\r\n</ul>\r\n<hr>\r\n<h2>Identit&eacute;, mission et valeurs</h2>\r\n<ul>\r\n<li>\r\n<p>Institution g&eacute;r&eacute;e par la <strong>Congr&eacute;gation sal&eacute;sienne de Don Bosco</strong>, visant &agrave; former des \"bons chr&eacute;tiens et citoyens loyaux, comp&eacute;tents et honn&ecirc;tes\"&nbsp;</p>\r\n</li>\r\n<li>\r\n<p><strong>Devise :</strong> &laquo; Solidarit&eacute; &ndash; Innovation &ndash; Travail &raquo;</p>\r\n</li>\r\n</ul>\r\n<hr>\r\n<h2>Offres acad&eacute;miques</h2>\r\n<h3>Facult&eacute;s existantes :</h3>\r\n<ul>\r\n<li>\r\n<p>Informatique</p>\r\n</li>\r\n<li>\r\n<p>Gestion &amp; ing&eacute;nierie financi&egrave;re</p>\r\n</li>\r\n<li>\r\n<p>Sciences humaines &amp; sociales</p>\r\n</li>\r\n<li>\r\n<p>Th&eacute;ologie</p>\r\n</li>\r\n</ul>\r\n<h3>Facult&eacute;s en projet :</h3>\r\n<ul>\r\n<li>\r\n<p>Logistique, banques &amp; assurances</p>\r\n</li>\r\n<li>\r\n<p>Sciences polytechniques &amp; environnement</p>\r\n</li>\r\n</ul>\r\n<hr>\r\n<h2>Activit&eacute;s &amp; &eacute;v&eacute;nements r&eacute;cents</h2>\r\n<ul>\r\n<li>\r\n<p><strong>Lancement officiel :</strong> 2 septembre 2023, &agrave; Lubumbashi, avec c&eacute;r&eacute;monie et pr&eacute;sentation du projet accessibles depuis ACP Haut‑Katanga</p>\r\n</li>\r\n<li>\r\n<p><strong>Premi&egrave;re promotion dipl&ocirc;m&eacute;e :</strong> septembre 2024, environ 100 dipl&ocirc;m&eacute;s (licences &amp; masters); c&eacute;r&eacute;monie au campus Karavia</p>\r\n</li>\r\n<li>\r\n<p><strong>Journ&eacute;es scientifiques :</strong> avril 2024 avec th&egrave;me &laquo; &Eacute;cologie responsable &raquo;, en pr&eacute;sence de professeurs, &eacute;tudiants, entreprises, relais religieux</p>\r\n</li>\r\n<li>\r\n<p><strong>Auto-&eacute;valuation institutionnelle :</strong> mars 2025, s&eacute;lection parmi 8 universit&eacute;s congolaises pour d&eacute;marches avec ANAQ‑ESU</p>\r\n</li>\r\n<li>\r\n<p><strong>Journ&eacute;e scientifique Justice &amp; Paix :</strong> mai 2025, organis&eacute;e par la facult&eacute; des sciences humaines et sociales</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>Information</th>\r\n<th>D&eacute;tails</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>Cr&eacute;ation</strong></td>\r\n<td>2023, fusion de 4 instituts sal&eacute;siens</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Type</strong></td>\r\n<td>Universit&eacute; priv&eacute;e catholique sal&eacute;sienne</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Lieu</strong></td>\r\n<td>Lubumbashi, Haut‑Katanga, RDC</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Facult&eacute;s actives</strong></td>\r\n<td>Informatique, Gestion, Sciences humaines, Th&eacute;ologie</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Valeurs</strong></td>\r\n<td>Solidarit&eacute;, Innovation, Travail</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Activit&eacute;s r&eacute;centes</strong></td>\r\n<td>Lancement officiel, premi&egrave;res dipl&ocirc;m&eacute;s, &eacute;v&eacute;nements scientifiques, &eacute;valuation qualit&eacute;</td>\r\n</tr>\r\n</tbody>\r\n</table>', '05, AV. FEMMES KATANGAISES, LUBUMBASHI - RDC', 'infos@udbl.ac.cd', '', 'https://udbl.ac.cd/', '1751469997_527e35bf84e01338cdf7.webp', NULL, '2025-05-29 14:05:29', '2025-07-02 13:51:52', '2025-07-02 13:51:52'),
